// One saved score: a line of scores.txt (chapter 7)
class ScoreEntry
{
    public string Username { get; set; }
    public int Score { get; set; }
    public string Date { get; set; }

    // Makes one score from its three parts
    public ScoreEntry(string username, int score, string date)
    {
        Username = username;
        Score = score;
        Date = date;
    }

    // The score as one line of scores.txt
    public override string ToString()
    {
        return Username + "|" + Score + "|" + Date;
    }
}

// Reads and adds to scores.txt, and works out the Top 10 (chapter 7)
static class ScoreFile
{
    // Reads every score in scores.txt into a list
    public static List<ScoreEntry> LoadAll()
    {
        List<ScoreEntry> scores = new List<ScoreEntry>();
        string path = Files.Data("scores.txt");
        if (!File.Exists(path)) return scores;    // no file: no scores
        StreamReader reader = new StreamReader(path);
        while (!reader.EndOfStream)
        {
            string line = reader.ReadLine();
            string[] parts = line.Split('|');
            if (parts.Length != 3) continue;      // skip a broken line
            scores.Add(new ScoreEntry(parts[0],
                Convert.ToInt32(parts[1]), parts[2]));
        }
        reader.Close();
        return scores;
    }

// Adds one score to the end of scores.txt
public static void Save(ScoreEntry e)
{
    StreamWriter writer = new StreamWriter(Files.Data("scores.txt"),
        true);                                // true: add to the end
    writer.WriteLine(e.ToString());
    writer.Close();
}

// The player's most recent score, or -1 if there are none
public static int LastScore(string username)
{
    int last = -1;
    foreach (ScoreEntry e in LoadAll())
    {
        if (e.Username == username) last = e.Score;
    }
    return last;
}

// The player's highest score, or -1 if there are none
public static int BestScore(string username)
{
    int best = -1;
    foreach (ScoreEntry e in LoadAll())
    {
        if (e.Username == username && e.Score > best) best = e.Score;
    }
    return best;
}

// The ten best players, highest first; empty places are null
public static ScoreEntry[] TopTen()
{
    // First pass: keep each player's best score
    Dictionary<string, ScoreEntry> best =
        new Dictionary<string, ScoreEntry>();
    foreach (ScoreEntry e in LoadAll())
    {
        if (!best.ContainsKey(e.Username)) best.Add(e.Username, e);
        else if (e.Score > best[e.Username].Score)
        {
            best[e.Username] = e;
        }
    }
    // Second pass: copy the bests into an array
    ScoreEntry[] all = new ScoreEntry[best.Count];
    int n = 0;
    foreach (string name in best.Keys)
    {
        all[n] = best[name];
        n++;
    }

// Bubble sort: higher score first, equal scores A to Z
for (int pass = 0; pass < all.Length - 1; pass++)
{
    for (int i = 0; i < all.Length - 1 - pass; i++)
    {
        if (ComesBefore(all[i + 1], all[i]))
        {
            ScoreEntry keep = all[i];
            all[i] = all[i + 1];
            all[i + 1] = keep;
        }
    }
}
// The first ten go on the board
ScoreEntry[] top = new ScoreEntry[10];
for (int i = 0; i < 10 && i < all.Length; i++) top[i] = all[i];
return top;

// True when score a belongs above score b on the board
private static bool ComesBefore(ScoreEntry a, ScoreEntry b)
{
    if (a.Score > b.Score) return true;
    if (a.Score < b.Score) return false;
    return string.Compare(a.Username, b.Username, true) < 0;
}

// The player's place on the board, 1 to 10, or 0 if not on it
public static int PlaceOf(string username)
{
    ScoreEntry[] top = TopTen();
    for (int i = 0; i < 10; i++)
    {
        if (top[i] != null && top[i].Username == username)
        {
            return i + 1;
        }
    }
    return 0;
}

// The score in 10th place, or -1 if fewer than 10 have scored
public static int TenthPlaceScore()
{
    ScoreEntry[] top = TopTen();
    if (top[9] == null) return -1;
    return top[9].Score;
}

// The avatar file of a player, or "" if there is no such player
public static string AvatarOf(string username)
{
    List<Player> players = LoadAll();
    foreach (Player p in players)
    {
        if (p.Username == username) return p.Avatar;
    }
    return "";
}

private string[] avatarFiles = { "avatar-goat.png",
    "avatar-eagle.png", "avatar-fox.png", "avatar-hare.png",
    "avatar-deer.png", "avatar-owl.png", "avatar-badger.png",
    "avatar-raven.png" };

// Loads the avatar pictures, then fills the whole screen
private void frmWelcome_Load(object sender, EventArgs e)
{
    // The board's small pictures, one for each avatar file
    foreach (string file in avatarFiles)
    {
        Image picture = Files.Picture("Avatars", file);
        if (picture != null) imgAvatars.Images.Add(file, picture);
    }
    // Player was added first, so it can show the avatar picture;
    // these two lines put Place first on the screen
    colPlace.DisplayIndex = 0;
    colPlayer.DisplayIndex = 1;
    picTrophy.Image = Files.Picture("Icons", "icon-trophy-64.png");
    mnuSound.Checked = !Sound.Muted;
    ShowEverything();
}

// Fills the whole screen: the player, the banner and the board
private void ShowEverything()
{
    ShowPlayer();
    ShowBanner();
    ShowBoard();
}

// The left card: avatar, hello, last score and best score
private void ShowPlayer()
{
    string name = Expedition.CurrentPlayer.Username;
    picAvatar.Image = Files.Picture("Avatars",
        Expedition.CurrentPlayer.Avatar);
    int last = ScoreFile.LastScore(name);
    if (last == -1)
    {
        lblHello.Text = "Welcome to Summit Ready, " + name + ".";
        lblLast.Text = "You have not finished an expedition yet.";
        lblBest.Visible = false;
    }
    else
    {
        lblHello.Text = "Welcome back, " + name + ".";
        lblLast.Text = "Your last score: " + last + " points.";
        lblBest.Text = "Your best score: "
            + ScoreFile.BestScore(name) + " points.";
        lblBest.Visible = true;
    }
}

// The banner shows once, straight after a saved expedition
private void ShowBanner()
{
    MoveBoard(false);
}

// Puts the board under the banner, or back at the top
private void MoveBoard(bool bannerShowing)
{
    pnlBanner.Visible = bannerShowing;
    int top = 40;
    if (bannerShowing) top = 156;
    lblTopTitle.Top = top;
    lvTop.Top = top + 34;
    lblNoScores.Top = top + 34;
}

// The Top 10: one row for each player, with their best score
private void ShowBoard()
{
    string name = Expedition.CurrentPlayer.Username;
    ScoreEntry[] top = ScoreFile.TopTen();
    lvTop.Items.Clear();
    lblNoScores.Visible = top[0] == null;
    lvTop.Visible = top[0] != null;
    for (int i = 0; i < 10; i++)
    {
        if (top[i] == null) break;    // nobody in this place yet
        ListViewItem row = new ListViewItem(top[i].Username);
        row.ImageKey = PlayerFile.AvatarOf(top[i].Username);
        row.SubItems.Add(Mix.Ordinal(i + 1));
        row.SubItems.Add(top[i].Score + " points");
        row.SubItems.Add(top[i].Date);
        lvTop.Items.Add(row);
    }
}

// The Top 10: one row for each player, with their best score
private void ShowBoard()
{
    string name = Expedition.CurrentPlayer.Username;
    ScoreEntry[] top = ScoreFile.TopTen();
    lvTop.Items.Clear();
    lblNoScores.Visible = top[0] == null;
    lvTop.Visible = top[0] != null;
    for (int i = 0; i < 10; i++)
    {
        if (top[i] == null) break;    // nobody in this place yet
        ListViewItem row = new ListViewItem(top[i].Username);
        row.ImageKey = PlayerFile.AvatarOf(top[i].Username);
        row.SubItems.Add(Mix.Ordinal(i + 1));
        row.SubItems.Add(top[i].Score + " points");
        row.SubItems.Add(top[i].Date);
        if (top[i].Username == name)
        {
            row.BackColor = Color.FromArgb(255, 241, 193);
            row.Font = new Font(lvTop.Font, FontStyle.Bold);
        }
        lvTop.Items.Add(row);
    }
}

// The banner's OK button hides it
private void btnBannerOK_Click(object sender, EventArgs e)
{
    MoveBoard(false);
}

// Game, then Log out: back to the log in form
private void mnuLogOut_Click(object sender, EventArgs e)
{
    DialogResult answer = MessageBox.Show("Log out of Summit Ready?",
        "Summit Ready", MessageBoxButtons.YesNo);
    if (answer == DialogResult.Yes) this.Close();
}

// Game, then Exit
private void mnuExit_Click(object sender, EventArgs e)
{
    Application.Exit();
}

// Sound, then Sound on: the tick shows when the sound is on
private void mnuSound_Click(object sender, EventArgs e)
{
    Sound.Muted = !Sound.Muted;
    mnuSound.Checked = !Sound.Muted;
}

// Help, then How to play
private void mnuHow_Click(object sender, EventArgs e)
{
    MessageBox.Show("Log in, then press Start the expedition. Climb "
        + "the eight summits in any order. Each summit is a "
        + "different game worth up to 100 points. When you finish, "
        + "you see what went well and what went wrong in each game, "
        + "and whether you made the Top 10.", "How to play");
}

// Help, then About Summit Ready
private void mnuAbout_Click(object sender, EventArgs e)
{
    MessageBox.Show("Summit Ready is a teaching example for AS "
        + "Software Systems Development. Pictures come from "
        + "OpenMoji, Wikimedia Commons and OpenTopoMap. Sounds come "
        + "from Kenney and Wikimedia Commons. Every credit is in "
        + "credits.txt beside the program.", "About Summit Ready");
}
